    updatedProfile.email,
    initialProfile.email,
  );
  TestValidator.equals(
    "created_at unchanged",
    updatedProfile.created_at,
    originalCreatedAt,
  );
  TestValidator.equals("deleted_at is null", updatedProfile.deleted_at, null);
}

