    profile.email,
    registration.email,
  );
  TestValidator.equals(
    "display_name matches registration",
    profile.display_name,
    registration.display_name,
  );
  // 4. Verify deleted_at is null for active account
  TestValidator.equals(
    "deleted_at is null for active account",
