      skip,
      take: limit,
      ...TodoAppTodoAtSummaryTransformer.select(),
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where: whereInput,
    }),
  ]);
  const pages: number & tags.Type<"int32"> & tags.Minimum<0> = Math.ceil(
    total / limit,
  );
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
